#define SDL_MAIN_HANDLED
#include "libs/tincle.h"
#include "libs/SDL_scancode.h"
#include "libs/SDL2_gfxPrimitives.h"
#include <stdio.h>
float ex=640,ev=320,cd=0,sh=0; int sc=0,hi=0,fnt=-1,l_in=0,st=0; SDL_Renderer* R; char buf[80];
void up(float dt){ int k=tincle_key_pressed(SDL_SCANCODE_SPACE)||tincle_mouse_pressed(1),t=k&&!l_in; l_in=k; sh*=0.85f; if(st==0){if(t){ex=640;ev=320;sc=0;cd=0;st=1;tincle_change_state(1);}return;} if(st==2){if(t){st=0;tincle_change_state(0);}return;} if(t&&cd<=0)cd=0.35f; cd-=dt; ex-=ev*dt; if(ex<110){sh=20;st=2;tincle_change_state(2);} if(ex<175&&ex>105&&cd>0.2f){ex=640;ev+=45;if(++sc>hi)hi=sc;sh=15;if(sc>=10){st=2;tincle_change_state(2);}} }
void dr(void){ int s=(int)sh*(rand()%3-1),p=cd>0.2f,x=(int)ex; tincle_clear((TinCLE_Color){st==2&&sc<10?70:p?50:20,st==2&&sc>=10?60:20,st==0?60:40,255}); boxRGBA(R,0,340,640,480,35,35,60,255); boxRGBA(R,80+s,280,112+s,340,0,180,220,255); filledCircleRGBA(R,96+s,262,14,255,220,180,255); boxRGBA(R,80+s,250,114+s,256,220,40,40,255); if(p){filledTrigonRGBA(R,112+s,230,185+s,295,112+s,340,255,255,100,230);boxRGBA(R,110+s,285,180+s,295,255,255,255,255);}else boxRGBA(R,105+s,305,135+s,311,180,190,210,255); if(st==1){boxRGBA(R,x,285,x+40,340,200,30,40,255);filledTrigonRGBA(R,x,285,x+12,265,x+20,285,255,180,0,255);filledTrigonRGBA(R,x+20,285,x+28,265,x+40,285,255,180,0,255);filledCircleRGBA(R,x+12,305,5,255,255,0,255);boxRGBA(R,x-18,308,x+5,314,255,80,80,255);sprintf(buf,"ISSEN:%d/10  HI:%d  [SPACE / CLICK]",sc,hi);tincle_draw_text(buf,20,20,(TinCLE_Color){255,255,80,255});}else{boxRGBA(R,90,100,550,240,10,10,25,220);tincle_draw_text_center(st==0?"=== ISSEN PARRY 8-LINES ===":sc>=10?"*** MASTER CLEAR!! ***":"--- GAME OVER ---",320,145,(TinCLE_Color){255,st==2&&sc<10?80:255,80,255});sprintf(buf,st==0?"LAST:%d/10  HI:%d/10  [SPACE/CLICK START]":"SCORE:%d/10  HI:%d/10  [SPACE/CLICK TO TITLE]",sc,hi);tincle_draw_text_center(buf,320,195,(TinCLE_Color){255,255,255,255});} } void game_load(void){ R=tincle_get_renderer(); fnt=tincle_load_font("font.ttf",24); tincle_set_font(fnt); tincle_add_state(0,up,dr); tincle_add_state(1,up,dr); tincle_add_state(2,up,dr); tincle_change_state(0); } int main(int a,char** v){ tincle_start(game_load,"ISSEN PARRY 8-LINES",false,640,480,TINCLE_MODE_2D_NORMAL); return 0; }
